function validate([grid]) {
  if (!Array.isArray(grid) || grid.length < 2 || grid.length > 1000) return 'grid needs 2 to 1000 rows.';
  const cols = Array.isArray(grid[0]) ? grid[0].length : 0;
  if (cols < 2 || cols > 1000) return 'Each row needs 2 to 1000 values.';
  if (grid.some(row => !Array.isArray(row) || row.length !== cols)) return 'All rows must have the same length.';
  if (grid.length * cols > 100000) return 'grid has at most 10^5 cells.';
  if (grid.some(row => row.some(v => !Number.isInteger(v) || v < 0 || v > 100000))) return 'Each value is an integer from 0 to 10^5.';
  if (grid[0][0] !== 0) return 'grid[0][0] must be 0.';
  return null;
}

