function minimumTime(grid) {
  const rows = grid.length;
  const cols = grid[0].length;
  if (grid[0][1] > 1 && grid[1][0] > 1) return -1;
  const dist = Array.from({ length: rows }, () => new Array(cols).fill(Infinity));
  const directions = [[1, 0], [-1, 0], [0, 1], [0, -1]];
  const heap = [];

  const push = (item) => {
    heap.push(item);
    let child = heap.length - 1;
    while (child > 0) {
      const parent = (child - 1) >> 1;
      if (heap[parent][0] <= heap[child][0]) break;
      [heap[parent], heap[child]] = [heap[child], heap[parent]];
      child = parent;
    }
  };
  const pop = () => {
    const top = heap[0];
    const last = heap.pop();
    if (heap.length === 0) return top;
    heap[0] = last;
    let parent = 0;
    while (true) {
      const left = 2 * parent + 1;
      const right = left + 1;
      let smallest = parent;
      if (left < heap.length && heap[left][0] < heap[smallest][0]) smallest = left;
      if (right < heap.length && heap[right][0] < heap[smallest][0]) smallest = right;
      if (smallest === parent) break;
      [heap[parent], heap[smallest]] = [heap[smallest], heap[parent]];
      parent = smallest;
    }
    return top;
  };

  dist[0][0] = 0;
  push([0, 0, 0]);
  while (heap.length > 0) {
    const [time, row, col] = pop();
    if (time > dist[row][col]) continue;
    if (row === rows - 1 && col === cols - 1) return time;
    for (const [dr, dc] of directions) {
      const nextRow = row + dr;
      const nextCol = col + dc;
      if (nextRow < 0 || nextRow >= rows || nextCol < 0 || nextCol >= cols) continue;
      const open = grid[nextRow][nextCol];
      const wait = (open - time) % 2 === 0 ? 1 : 0;
      const arrive = Math.max(time + 1, open + wait);
      if (arrive < dist[nextRow][nextCol]) {
        dist[nextRow][nextCol] = arrive;
        push([arrive, nextRow, nextCol]);
      }
    }
  }
  return -1;
}

