function minimumTime(grid) {
  // Simulate second by second: the set of cells you can be on at exactly time t.
  const m = grid.length, n = grid[0].length;
  let highest = 0;
  for (const line of grid) for (const v of line) highest = Math.max(highest, v);
  const limit = highest + 2 * (m + n) + 4;
  let current = new Set(['0,0']);
  for (let t = 0; t <= limit; t++) {
    if (current.has(`${m - 1},${n - 1}`)) return t;
    if (current.size === 0) return -1;
    const next = new Set();
    for (const key of current) {
      const [r, c] = key.split(',').map(Number);
      for (const [nr, nc] of [[r + 1, c], [r - 1, c], [r, c + 1], [r, c - 1]]) {
        if (nr >= 0 && nr < m && nc >= 0 && nc < n && grid[nr][nc] <= t + 1) next.add(`${nr},${nc}`);
      }
    }
    current = next;
  }
  return -1;
}

