function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const rows = size === 'large' ? pick(60, 100) : pick(2, 4);
  const cols = size === 'large' ? pick(60, 100) : pick(2, 4);
  const caps = size === 'large' ? [10, 300, 5000, 100000] : [1, 3, 6, 12];
  const top = caps[Math.floor(rand() * caps.length)];
  const walls = rand() < 0.5;
  const grid = Array.from({ length: rows }, (_, r) => Array.from({ length: cols }, (_, c) => {
    if (walls) return rand() < 0.3 ? pick(0, top) : pick(0, r + c);
    return pick(0, top);
  }));
  grid[0][0] = 0;
  // Most inputs let the first step happen; a few keep the start boxed in.
  if (rand() < 0.85) {
    if (rand() < 0.5) grid[0][1] = pick(0, 1);
    else grid[1][0] = pick(0, 1);
  }
  return [grid];
}
